<?php
require_once __DIR__ . '/_init.php'; require_perfil(['Admin']); $erro='';
if ($_SERVER['REQUEST_METHOD']==='POST') { verify_csrf(); $acao=$_POST['acao']??''; $id=(int)($_POST['id']??0); try { if ($acao==='salvar') { $nome=trim((string)($_POST['nome']??'')); $email=strtolower(trim((string)($_POST['email']??''))); $perfilNovo=(string)($_POST['perfil']??'Aluno'); $curso=trim((string)($_POST['curso']??'')); $senha=(string)($_POST['senha']??''); if(mb_strlen($nome)<3||!filter_var($email,FILTER_VALIDATE_EMAIL)||!in_array($perfilNovo,['Admin','Professor','Aluno'],true)) throw new RuntimeException('Confira os dados informados.'); if($id===0 && strlen($senha)<12) throw new RuntimeException('A senha inicial deve ter ao menos 12 caracteres.'); if($id>0) { if($senha!=='') { if(strlen($senha)<12) throw new RuntimeException('A senha deve ter ao menos 12 caracteres.'); $s=$pdo->prepare('UPDATE usuarios SET nome=:n,email=:e,perfil=:p,curso=:c,senha_hash=:h WHERE id=:id'); $s->execute([':n'=>$nome,':e'=>$email,':p'=>$perfilNovo,':c'=>$curso?:null,':h'=>password_hash($senha,PASSWORD_DEFAULT),':id'=>$id]); } else { $s=$pdo->prepare('UPDATE usuarios SET nome=:n,email=:e,perfil=:p,curso=:c WHERE id=:id'); $s->execute([':n'=>$nome,':e'=>$email,':p'=>$perfilNovo,':c'=>$curso?:null,':id'=>$id]); } audit($pdo,'atualizou usuário','usuarios',$id); } else { $s=$pdo->prepare("INSERT INTO usuarios(nome,email,senha_hash,perfil,curso,status) VALUES(:n,:e,:h,:p,:c,'ativo') RETURNING id"); $s->execute([':n'=>$nome,':e'=>$email,':h'=>password_hash($senha,PASSWORD_DEFAULT),':p'=>$perfilNovo,':c'=>$curso?:null]); $new=(int)$s->fetchColumn(); audit($pdo,'criou usuário','usuarios',$new); } header('Location: usuarios.php?ok=1'); exit; } elseif($acao==='status' && $id!==(int)$_SESSION['usuario_id']) { $s=$pdo->prepare("UPDATE usuarios SET status=CASE WHEN status='ativo' THEN 'inativo' ELSE 'ativo' END WHERE id=:id"); $s->execute([':id'=>$id]); audit($pdo,'alterou status de usuário','usuarios',$id); header('Location: usuarios.php?ok=1'); exit; } elseif($acao==='excluir' && $id!==(int)$_SESSION['usuario_id']) { audit($pdo,'solicitou exclusão de usuário','usuarios',$id); $s=$pdo->prepare('DELETE FROM usuarios WHERE id=:id'); $s->execute([':id'=>$id]); header('Location: usuarios.php?ok=1'); exit; } } catch(Throwable $e) { if($e instanceof PDOException) error_log($e->getMessage()); $erro=($e instanceof RuntimeException&&!($e instanceof PDOException)) ? $e->getMessage() : 'Não foi possível salvar. Verifique e-mail duplicado e dados.'; } }
$editar=null; if(isset($_GET['editar'])) { $s=$pdo->prepare('SELECT id,nome,email,perfil,curso,status FROM usuarios WHERE id=:id'); $s->execute([':id'=>(int)$_GET['editar']]); $editar=$s->fetch(); }
$usuarios=$pdo->query('SELECT id,nome,email,perfil,curso,status,criado_em FROM usuarios ORDER BY nome')->fetchAll(); admin_header('Gerenciar usuários'); if($erro): ?><div class="alert error"><?= h($erro) ?></div><?php endif; ?><section class="panel"><h2><?= $editar?'Editar usuário':'Criar usuário' ?></h2><form method="post"><input type="hidden" name="csrf_token" value="<?= h(csrf_token()) ?>"><input type="hidden" name="acao" value="salvar"><input type="hidden" name="id" value="<?= h($editar['id']??0) ?>"><label>Nome<input name="nome" required maxlength="150" value="<?= h($editar['nome']??'') ?>"></label><label>E-mail<input type="email" name="email" required maxlength="254" value="<?= h($editar['email']??'') ?>"></label><label>Perfil<select name="perfil"><option <?= (($editar['perfil']??'Aluno')==='Admin')?'selected':'' ?>>Admin</option><option <?= (($editar['perfil']??'')==='Professor')?'selected':'' ?>>Professor</option><option <?= (($editar['perfil']??'Aluno')==='Aluno')?'selected':'' ?>>Aluno</option></select></label><label>Curso<input name="curso" maxlength="150" value="<?= h($editar['curso']??'') ?>"></label><label><?= $editar?'Nova senha (opcional)':'Senha inicial (mínimo 12 caracteres)' ?><input type="password" name="senha" minlength="12" <?= $editar?'':'required' ?> autocomplete="new-password"></label><button type="submit">Salvar usuário</button></form></section><section class="panel"><h2>Contas cadastradas</h2><?php foreach($usuarios as $u): ?><article class="item"><div><h3><?= h($u['nome']) ?></h3><p><?= h($u['email']) ?> · <?= h($u['perfil']) ?> · <?= h($u['curso']?:'Sem curso') ?> · <?= h($u['status']) ?></p></div><div class="actions"><a class="button secondary" href="usuarios.php?editar=<?= (int)$u['id'] ?>">Editar</a><?php if((int)$u['id']!==(int)$_SESSION['usuario_id']): ?><form method="post"><input type="hidden" name="csrf_token" value="<?= h(csrf_token()) ?>"><input type="hidden" name="acao" value="status"><input type="hidden" name="id" value="<?= (int)$u['id'] ?>"><button class="secondary" type="submit"><?= $u['status']==='ativo'?'Desativar':'Ativar' ?></button></form><form method="post"><input type="hidden" name="csrf_token" value="<?= h(csrf_token()) ?>"><input type="hidden" name="acao" value="excluir"><input type="hidden" name="id" value="<?= (int)$u['id'] ?>"><button class="danger" type="submit">Excluir</button></form><?php endif; ?></div></article><?php endforeach; ?></section><?php admin_footer();
